'use strict';
const fs=require('node:fs');
const path=require('node:path');
const crypto=require('node:crypto');
const cp=require('node:child_process');

const idOk=id=>/^TASK-[0-9]{4}$/.test(String(id));
function sha256(bytes){return crypto.createHash('sha256').update(bytes).digest('hex')}
function location(home){return path.resolve(home||__dirname)}
function stateFile(home){return path.join(location(home),'state.json')}
function read(home){return JSON.parse(fs.readFileSync(stateFile(home),'utf8'))}
function atomic(file,content){
 const tmp=file+'.writing-'+process.pid;
 fs.writeFileSync(tmp,content,{encoding:'utf8',flag:'wx'});
 fs.renameSync(tmp,file);
}
function transaction(home,fn){
 const root=location(home),lock=path.join(root,'.write.lock');
 const fd=fs.openSync(lock,'wx');
 try{return fn(root)}
 finally{fs.closeSync(fd);fs.unlinkSync(lock)}
}
function write(home,s,event){
 atomic(stateFile(home),JSON.stringify(s,null,2)+'\n');
 fs.appendFileSync(path.join(home,'events.jsonl'),JSON.stringify(event)+'\n',{encoding:'utf8'});
}
function init(home){
 const root=location(home);
 fs.mkdirSync(root,{recursive:true});
 for(const d of ['tasks','reports','proofs'])fs.mkdirSync(path.join(root,d),{recursive:true});
 const f=stateFile(root);
 if(!fs.existsSync(f)){
  fs.writeFileSync(f,JSON.stringify({contract:'local.board.v1',tasks:{}},null,2)+'\n',{flag:'wx'});
  fs.appendFileSync(path.join(root,'events.jsonl'),JSON.stringify({event:'board_init',at:new Date().toISOString()})+'\n');
 }
 return read(root);
}
function enqueue(home,id,source){
 if(!idOk(id))throw new Error('TASK_ID_INVALID');
 const root=location(home),target=path.resolve(root,'tasks',id+'.md');
 if(path.resolve(source)!==target)throw new Error('TASK_PATH_NOT_CANONICAL');
 return transaction(root,()=>{
  const s=read(root);
  if(s.tasks[id])throw new Error('TASK_ALREADY_EXISTS');
  const bytes=fs.readFileSync(target);
  if(bytes.length<30)throw new Error('TASK_EMPTY');
  const record={state:'queued',taskPath:'tasks/'+id+'.md',taskSha256:sha256(bytes),createdAt:new Date().toISOString()};
  s.tasks[id]=record;
  write(root,s,{event:'queued',taskId:id,at:record.createdAt,taskSha256:record.taskSha256});
  return record;
 });
}
function evidence(home,id,reportFile,testFile){
 if(!idOk(id))throw new Error('TASK_ID_INVALID');
 const root=location(home);
 const report=path.resolve(reportFile),test=path.resolve(testFile);
 if(path.dirname(report)!==path.join(root,'reports'))throw new Error('REPORT_NOT_IN_ALLOWED_FOLDER');
 if(path.dirname(test)!==path.join(root,'tests') || !test.endsWith('.test.cjs'))
  throw new Error('TEST_NOT_IN_ALLOWED_FOLDER');
 return transaction(root,()=>{
  const s=read(root),rec=s.tasks[id];
  if(!rec||rec.state!=='queued')throw new Error('TASK_NOT_AWAITING_EVIDENCE');
  if(sha256(fs.readFileSync(path.join(root,rec.taskPath)))!==rec.taskSha256)
   throw new Error('TASK_CHANGED_SINCE_QUEUE');
  const bytes=fs.readFileSync(report);
  if(bytes.length<80)throw new Error('REPORT_TOO_SHORT');
  const result=cp.spawnSync(process.execPath,['--test',test],{cwd:root,timeout:60000,encoding:'utf8',windowsHide:true,maxBuffer:2_000_000});
  if(result.error)throw result.error;
  const resultFile=path.join(root,'proofs',id+'.test.log');
  fs.writeFileSync(resultFile,String(result.stdout||'')+String(result.stderr||''),{flag:'wx'});
  rec.state=result.status===0?'tested_pending_review':'tests_failed';
  rec.reportSha256=sha256(bytes);
  rec.testLog='proofs/'+id+'.test.log';
  rec.testExit=result.status;
  rec.checkedAt=new Date().toISOString();
  write(root,s,{event:rec.state,taskId:id,at:rec.checkedAt,reportSha256:rec.reportSha256,testExit:rec.testExit});
  return rec;
 });
}
function status(home){
 const s=read(home);
 return {contract:s.contract,total:Object.keys(s.tasks).length,tasks:s.tasks};
}
if(require.main===module){
 try{
  const [cmd,home,id,a,b]=process.argv.slice(2);
  const base=home||__dirname;
  const result=cmd==='init'?init(base):cmd==='status'?status(base)
    :cmd==='enqueue'?enqueue(base,id,a)
    :cmd==='evidence'?evidence(base,id,a,b)
    :(()=>{throw new Error('USAGE: node board.cjs <init|status|enqueue|evidence> <root> ...')})();
  process.stdout.write(JSON.stringify(result,null,2)+'\n');
 }catch(error){console.error('LOCAL_BOARD_ERROR '+String(error.message||error));process.exitCode=2}
}
module.exports={init,enqueue,evidence,status,sha256};

