'use strict';
const test=require('node:test');
const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const os=require('node:os');
const {init,enqueue,status,sha256}=require('../board.cjs');
function temp(){return fs.mkdtempSync(path.join(os.tmpdir(),'local-board-proof-'))}
test('creates local state and event log with no git remote or HTTP',()=>{
 const dir=temp();try{
  init(dir);const s=status(dir);
  assert.equal(s.contract,'local.board.v1');assert.equal(s.total,0);
  assert.match(fs.readFileSync(path.join(dir,'events.jsonl'),'utf8'),/board_init/);
 }finally{fs.rmSync(dir,{recursive:true,force:true})}
});
test('Markdown instruction is queued with SHA256 and cannot be duplicated',()=>{
 const dir=temp();try{
  init(dir);const f=path.join(dir,'tasks','TASK-0001.md');
  fs.writeFileSync(f,'# TASK-0001\n\nPerform isolated read-only analysis and collect local test evidence.\n');
  const row=enqueue(dir,'TASK-0001',f);
  assert.equal(row.state,'queued');assert.equal(row.taskSha256,sha256(fs.readFileSync(f)));
  assert.throws(()=>enqueue(dir,'TASK-0001',f),/TASK_ALREADY_EXISTS/);
  assert.equal(status(dir).total,1);
 }finally{fs.rmSync(dir,{recursive:true,force:true})}
});
test('rejects path traversal, malformed identifiers, and empty instructions',()=>{
 const dir=temp();try{
  init(dir);
  assert.throws(()=>enqueue(dir,'../escape','x'),/TASK_ID_INVALID/);
  assert.throws(()=>enqueue(dir,'TASK-0002',path.join(dir,'outside.md')),/TASK_PATH_NOT_CANONICAL/);
  const f=path.join(dir,'tasks','TASK-0002.md');
  fs.writeFileSync(f,'short');
  assert.throws(()=>enqueue(dir,'TASK-0002',f),/TASK_EMPTY/);
 }finally{fs.rmSync(dir,{recursive:true,force:true})}
});
test('does not silently approve a task with no verified report',()=>{
 const dir=temp();try{
  init(dir);const f=path.join(dir,'tasks','TASK-0003.md');
  fs.writeFileSync(f,'# TASK\n\nA local task must be independently tested and reviewed.\n');
  enqueue(dir,'TASK-0003',f);
  assert.equal(status(dir).tasks['TASK-0003'].state,'queued');
  assert.equal(status(dir).tasks['TASK-0003'].checkedAt,undefined);
 }finally{fs.rmSync(dir,{recursive:true,force:true})}
});

